function predictionRecentPowerFromRows(rows = [], options = {}) {
  const bbe = (Array.isArray(rows) ? rows : []).map((row) => ({
    launchSpeed: savantRate(row, ['launch_speed', 'Launch Speed', 'exit_velocity', 'Exit Velocity']),
    launchAngle: savantRate(row, ['launch_angle', 'Launch Angle']),
    launchSpeedAngle: csvValue(row, ['launch_speed_angle', 'Launch Speed Angle']),
    bbType: cleanSummary(csvValue(row, ['bb_type', 'BB Type', 'batted_ball_type'])).toLowerCase(),
    stand: handednessCode(csvValue(row, ['stand', 'Stand', 'batter_stand'])),
    hcX: savantRate(row, ['hc_x', 'HC X']),
    estimatedSlg: savantRate(row, ['estimated_slg_using_speedangle', 'estimated_slg', 'xslg']),
    estimatedWoba: savantRate(row, ['estimated_woba_using_speedangle', 'estimated_woba', 'xwoba']),
  })).filter((row) => Number.isFinite(Number(row.launchSpeed)) && row.bbType);
  const n = bbe.length;
  if (!n) return { ...predictionRecentPowerNeutral(), recentPowerStatsAsOf: options.statsAsOf || '' };
  const hardHitPct = (bbe.filter((row) => Number(row.launchSpeed) >= 95).length / n) * 100;
  const avgEv = bbe.reduce((sum, row) => sum + Number(row.launchSpeed), 0) / n;
  const maxEv = Math.max(...bbe.map((row) => Number(row.launchSpeed)));
  const barrelRows = bbe.filter((row) => String(row.launchSpeedAngle || '').trim() !== '');
  const barrelPct = barrelRows.length ? (barrelRows.filter((row) => {
    const value = String(row.launchSpeedAngle || '').trim().toLowerCase();
    return value === '6' || value === 'barrel';
  }).length / n) * 100 : null;
  const flyRows = bbe.filter((row) => row.bbType);
  const airRows = flyRows.filter((row) => ['fly_ball', 'line_drive'].includes(row.bbType));
  const flyballPct = flyRows.length ? (airRows.length / n) * 100 : null;
  const pullAirRows = airRows.filter((row) => {
    const x = Number(row.hcX);
    if (!Number.isFinite(x) || !['L', 'R'].includes(row.stand)) return false;
    return row.stand === 'R' ? x < 125 : x > 125;
  });
  const airPullPct = airRows.length ? (pullAirRows.length / airRows.length) * 100 : null;
  const angleRows = bbe.filter((row) => Number.isFinite(Number(row.launchAngle)));
  const sweetSpotPct = angleRows.length ? (angleRows.filter((row) => Number(row.launchAngle) >= 8 && Number(row.launchAngle) <= 32).length / n) * 100 : null;
  const xslgRows = bbe.filter((row) => Number.isFinite(Number(row.estimatedSlg)));
  const xwobaRows = bbe.filter((row) => Number.isFinite(Number(row.estimatedWoba)));
  const recentXslg = xslgRows.length ? xslgRows.reduce((sum, row) => sum + Number(row.estimatedSlg), 0) / xslgRows.length : null;
  const recentXwoba = xwobaRows.length ? xwobaRows.reduce((sum, row) => sum + Number(row.estimatedWoba), 0) / xwobaRows.length : null;
  let signal = 50;
  signal += (hardHitPct - 40) * 0.55;
  signal += (avgEv - 89) * 2.0;
  signal += (maxEv - 108) * 0.7;
  if (barrelPct !== null) signal += (barrelPct - 8) * 1.5;
  if (flyballPct !== null) signal += (flyballPct - 40) * 0.25;
  if (airPullPct !== null) signal += (airPullPct - 35) * 0.20;
  if (sweetSpotPct !== null) signal += (sweetSpotPct - 33) * 0.25;
  if (recentXslg !== null) signal += (recentXslg - 0.430) * 35;
  if (recentXwoba !== null) signal += (recentXwoba - 0.330) * 30;
  const reliability = Math.min(n / 25, 1);
  signal = clamp(50 + (reliability * (signal - 50)), 0, 100);
  const sampleValid = n >= 5;
  const adjustment = sampleValid
    ? clamp((signal - 50) / 5, -10, 10)
    : clamp((signal - 50) / 5, -1.5, 1.5);
  return {
    recentBbe: n,
    recentHardHitPct: Number(hardHitPct.toFixed(1)),
    recentBarrelPct: barrelPct === null ? undefined : Number(barrelPct.toFixed(1)),
    recentAvgEv: Number(avgEv.toFixed(1)),
    recentMaxEv: Number(maxEv.toFixed(1)),
    recentFlyballPct: flyballPct === null ? undefined : Number(flyballPct.toFixed(1)),
    recentAirPullPct: airPullPct === null ? undefined : Number(airPullPct.toFixed(1)),
    recentSweetSpotPct: sweetSpotPct === null ? undefined : Number(sweetSpotPct.toFixed(1)),
    recentXslg: recentXslg === null ? undefined : Number(recentXslg.toFixed(3)),
    recentXwoba: recentXwoba === null ? undefined : Number(recentXwoba.toFixed(3)),
    recentPowerSignal: Number(signal.toFixed(1)),
    recentPowerAdjustment: Number(adjustment.toFixed(1)),
    recentPowerReliability: Number(reliability.toFixed(3)),
    recentPowerSampleValid: sampleValid,
    recentPowerStatsAsOf: options.statsAsOf || '',
    recentPowerSource: 'baseball_savant_statcast_recent_batted_ball_power',
  };
}

async function getRecentBattedBallPower(playerId, endDate = predictionSnapshotDate(), days = 14) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0 || !endDate) return predictionRecentPowerNeutral();
  const safeDays = Math.max(1, Number(days) || 14);
  const startDate = addDaysToDateValue(endDate, -safeDays);
  const requestEndDate = endDate;
  const statsAsOf = `${endDate}T23:59:59`;
  const cacheKey = `${id}:${startDate}:${endDate}:${requestEndDate}:${safeDays}`;
  if (savantRecentPowerCache.has(cacheKey)) return savantRecentPowerCache.get(cacheKey);
  const promise = (async () => {
    const rows = parseCsvRows(await getText(predictionRecentPowerUrl(id, startDate, requestEndDate)));
    return predictionRecentPowerFromRows(rows, { statsAsOf });
  })().catch((error) => {
    savantRecentPowerCache.delete(cacheKey);
    return { ...predictionRecentPowerNeutral(), recentPowerStatsAsOf: statsAsOf, recentPowerError: error?.message || 'recent Statcast power unavailable' };
  });
  savantRecentPowerCache.set(cacheKey, promise);
  return promise;
}

